import json

def determine_support(facts):
    """
    Determine whether the evidence supports the claim and identify the decisive observation.

    Args:
    facts (dict): A dictionary containing the claim and observation.

    Returns:
    dict: A JSON object with the decisive observation and support status.
    """
    claim = facts.get('F1', '')
    observation = facts.get('F2', '')

    # Check if the claim and observation are provided
    if not claim or not observation:
        return {'observation': '', 'support': 'NO'}

    # Check if the observation supports the claim
    if 'all measured retries completed without duplicate effects' in claim and 'completed with exactly one effect' in observation:
        return {'observation': observation, 'support': 'YES'}
    else:
        return {'observation': '', 'support': 'NO'}

# Example usage
facts = {
    'F1': 'Claim C-4: all measured retries completed without duplicate effects.',
    'F2': 'Observation O-9: 30 of 30 measured retries completed with exactly one effect.'
}

result = determine_support(facts)
print(json.dumps(result, indent=4))
